import {allProducts,normalizeProduct,saveCatalog,CATALOG_KEY,money,readDemoOrders,write} from './catalog.js';
const $=selector=>document.querySelector(selector),$$=selector=>[...document.querySelectorAll(selector)];
const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
let working=allProducts.map(product=>({...product})),editingId=null;
function toast(message){const node=$('#adminToast');node.textContent=message;node.classList.add('show');clearTimeout(window.adminToastTimeout);window.adminToastTimeout=setTimeout(()=>node.classList.remove('show'),3500);}
function persist(list,message){if(!saveCatalog(list)){toast('Could not save. Check product IDs, prices and stock.');return false;}working=list.map(normalizeProduct);render();toast(message);return true;}
function download(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function orderDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?'Date unavailable':new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short'}).format(date);}
function render(){const visible=working.filter(p=>p.published),orders=readDemoOrders();$('#adminPublished').textContent=visible.length;$('#adminStock').textContent=visible.reduce((sum,p)=>sum+p.stock,0).toLocaleString('en-IN');$('#adminSoldOut').textContent=visible.filter(p=>p.stock===0).length;$('#adminOrders').textContent=orders.length;
 $('#catalogRows').innerHTML=working.map(p=>`<tr><td><strong>${escape(p.name)}</strong><small>${escape(p.id)}</small></td><td>${escape(p.type)}</td><td>${money(p.price)}</td><td>${p.stock}</td><td><span class="admin-status ${p.published?p.stock===0?'out':'':'hidden'}">${p.published?p.stock===0?'SOLD OUT':'VISIBLE':'HIDDEN'}</span></td><td><div class="admin-row-actions"><button type="button" data-edit="${escape(p.id)}" aria-label="Edit ${escape(p.name)}">Edit</button><button type="button" data-toggle="${escape(p.id)}" aria-label="${p.published?'Hide':'Show'} ${escape(p.name)}">${p.published?'Hide':'Show'}</button></div></td></tr>`).join('')||'<tr><td colspan="6">No products. Add one to start the catalog.</td></tr>';
 $('#orderRows').innerHTML=orders.length?orders.map(order=>`<article class="admin-order"><div><strong>${escape(order.id)}</strong><small>${orderDate(order.date)}</small></div><div><strong>${order.items?.reduce((sum,i)=>sum+(Number(i.qty)||0),0)??0} items</strong><small>${escape((order.items||[]).map(i=>working.find(p=>p.id===i.id)?.name||i.id).join(', '))}</small></div><div><strong>${money(Number(order.total)||0)}</strong><small>DEMO · NO PAYMENT</small></div></article>`).join(''):'<p class="admin-order-empty">No demo receipts in this browser yet. A completed demo checkout will appear here.</p>';
}
function editProduct(id=null){editingId=id;const form=$('#editorForm');form.reset();const product=id?working.find(p=>p.id===id):null;$('#editorTitle').textContent=product?'EDIT PRODUCT.':'ADD PRODUCT.';for(const key of ['name','id','price','stock','type','defaultColor','tag','subtitle','description','detail','case','display','brightness','battery','water','gps','weight','madeFor']){const field=form.elements.namedItem(key);field.value=product?.[key]??({stock:20,type:'everyday',defaultColor:'graphite'}[key]??'');}form.elements.namedItem('id').readOnly=Boolean(product);form.elements.namedItem('published').checked=product?.published??true;$('#productEditor').showModal();form.elements.namedItem('name').focus();}
function handleSave(event){event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form).entries());data.id=editingId||data.id;data.published=form.elements.namedItem('published').checked;data.tone=working.find(p=>p.id===editingId)?.tone??'pro';const product=normalizeProduct(data);if(!product){toast('Check product ID, price and stock.');return;}if(!editingId&&working.some(p=>p.id===product.id)){toast('That product ID is already used.');return;}const next=editingId?working.map(p=>p.id===editingId?product:p):[...working,product];if(persist(next,editingId?'Product updated in this browser.':'Product added in this browser.'))$('#productEditor').close();}
$('#newProduct').onclick=()=>editProduct();$('#editorForm').onsubmit=handleSave;$('#closeEditor').onclick=()=>$('#productEditor').close();$('#cancelEditor').onclick=()=>$('#productEditor').close();
$('#catalogRows').addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.dataset.edit){editProduct(button.dataset.edit);return;}if(button.dataset.toggle){const next=working.map(p=>p.id===button.dataset.toggle?{...p,published:!p.published}:p);persist(next,'Storefront visibility updated in this browser.');}});
$('#exportCatalog').onclick=()=>download('xeight-catalog-demo.json',{version:1,products:working});
$('#importCatalog').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text()),list=Array.isArray(data)?data:data.products;if(!Array.isArray(list)||list.length>30||!list.every(normalizeProduct)){toast('Invalid catalog JSON. Use a valid X EIGHT export.');return;}const ids=list.map(p=>String(p.id));if(new Set(ids).size!==ids.length){toast('Catalog has duplicate IDs.');return;}persist(list,'Catalog imported into this browser.');}catch{toast('Could not read that JSON file.');}finally{event.target.value='';}};
$('#resetCatalog').onclick=()=>{if(!confirm('Reset the local catalog to the six sample watches? This removes your local product edits.'))return;localStorage.removeItem(CATALOG_KEY);location.reload();};
$('#exportOrders').onclick=()=>download('xeight-demo-receipts.json',{version:1,orders:readDemoOrders()});
$('#clearOrders').onclick=()=>{if(!confirm('Clear the demo receipts stored in this browser?'))return;localStorage.removeItem('xeight-demo-orders');localStorage.removeItem('xeight-last-demo-order');render();toast('Local demo receipts cleared.');};
render();
